/* ===== configurações ===== */
/* cadastros em abas na horizontal: o nome de cada um fica sempre à vista e o conteúdo abre embaixo */
let SECS=[],LIBTAM="";
const EXPL={
banho:`<div class="expl"><b>Para que serve esta aba</b><p>Aqui você diz <b>qual galvânica</b> banha as peças e <b>quanto cada banho custa</b>. Cada banho que você marca ao lançar uma peça vira uma linha na planilha (ex.: a mesma argola em Ouro e em Prata gera 2 linhas).</p><ul><li><b>Letra do banho:</b> uma letra que entra no código da peça. Ex.: AN001<b>A</b> = anel 001, banho A. Vai na coluna E.</li><li><b>Custo do banho (colunas R, S ou T):</b> o valor que a galvânica cobra. Pode ser por peso (peso da peça × valor por grama) ou um valor fixo por peça. O verniz tem coluna própria (U).</li><li><b>Milésimos:</b> a espessura do banho. Quanto maior, mais caro. Você pode ter um valor diferente por categoria; a linha “Padrão” vale para as categorias que você não ajustou.</li><li><b>Insumos:</b> o que se gasta além do metal (embalagem, fecho, etc.). Soma no custo (coluna Q).</li><li><b>Preço de Varejo (coluna V):</b> é a soma dos custos multiplicada pelo <b>fator</b> do banho (a sua margem). Ex.: custo total R$ 10 × fator 3 = R$ 30.</li></ul></div>`,
cor:`<div class="expl"><b>Para que serve esta aba</b><p>É a sua lista de <b>cores</b> e de <b>tamanhos/variações</b> (aro de anel, P M G, medidas…). O que você cria aqui aparece nos botões <b>＋ Cor da pedra</b> e <b>＋ Tamanho</b> na hora de lançar uma peça.</p><ul><li><b>Sigla:</b> letras curtas que entram no código da peça. Ex.: AN001A<b>17</b><b>AZ</b> = anel 001, banho A, tamanho 17, cor azul.</li><li><b>Palavra na descrição:</b> o que aparece no fim da descrição da peça. Ex.: a cor “Azul” pode escrever “azul turquesa”. Deixe vazio para usar o nome da cor; digite um traço (-) para não escrever nada.</li><li><b>Coluna do valor (nas variações):</b> a coluna da planilha que recebe o nome da opção. Cada opção marcada gera uma linha.</li><li><b>Pedra/detalhe:</b> marque nas cores que são cor de pedra. As cores de banho (Ouro, Prata…) ficam de fora porque o banho já tem sua própria escolha.</li></ul></div>`,
cat:`<div class="expl"><b>Para que serve esta aba</b><p>Aqui você organiza os <b>tipos de peça</b> (Brincos, Colares, Anéis…) e define como o <b>código</b> de cada peça é numerado.</p><ul><li><b>Categoria e subcategoria:</b> o tipo da peça. Ex.: categoria <i>Brincos</i>, subcategoria <i>Argola</i>. Vão para as colunas I e J.</li><li><b>Prefixo:</b> as letras do código. Ex.: BR para Brincos.</li><li><b>Última peça:</b> o último número que você já usou. O sistema continua dali: prefixo BR + última peça 1669 → a próxima peça é <b>BR1670</b>. Se duas categorias usam o mesmo prefixo, elas dividem a mesma contagem e os números nunca se repetem.</li><li><b>Texto da categoria na Descrição:</b> uma frase que o sistema escreve <b>sozinho no fim da descrição</b> de toda peça dessa categoria. Ex.: na categoria Prata 925, texto “Prata 925”: você digita “Argola lisa” e a planilha sai com “Argola lisa Prata 925”. Se a descrição já tiver esse texto, ele não repete. Vazio = não acrescenta nada.</li><li><b>NCM, CFOP e FCP:</b> códigos fiscais que o ERP pede (colunas Y, AA e AB). <b>Insumos:</b> custo do material extra, como embalagem (coluna Q). Se ficar vazio, vale o padrão da coluna.</li><li><b>Variação (tamanhos, letras…):</b> fica dentro da categoria. Ao escolher a categoria ao lançar, as opções aparecem sozinhas, só para ela.</li></ul></div>`,
forn:`<div class="expl"><b>Para que serve esta aba</b><p>Lista dos seus <b>fornecedores</b>. Ao escolher o fornecedor ao lançar uma peça, o sistema já preenche o resto.</p><ul><li><b>Nome</b> vai para a coluna H e o <b>código do fornecedor</b> para a G.</li><li><b>Desconto %:</b> abatimento que esse fornecedor dá. É aplicado ao custo de compra (coluna P). Ex.: custo R$ 100 com 10% = R$ 90.</li><li><b>Bruta ou pronta:</b> “bruta” é a peça que chega sem banho e vai para a galvânica (você escolhe os banhos). “Pronta” já chega banhada e não passa pela galvânica.</li><li><b>Aprendeu:</b> guarda os banhos e fatores que você usou da última vez com esse fornecedor, para reaproveitar.</li></ul></div>`,
col:`<div class="expl"><b>Para que serve esta aba</b><p>A planilha que você exporta tem várias colunas. Aqui você escolhe <b>como cada coluna se comporta enquanto você lança a peça</b>. Isto muda só o preenchimento, não a planilha final (isso é na aba Modelo da planilha).</p><ul><li><b>No lançamento:</b> mostra o campo no formulário. Desmarcado, o campo some do formulário.</li><li><b>Lembrar:</b> repete o valor digitado na próxima peça (útil para o que não muda, como o fornecedor).</li><li><b>Obrigatória:</b> o sistema não deixa lançar se estiver vazio.</li><li><b>Valor padrão:</b> entra sozinho quando você não preenche.</li><li><b>Opções:</b> lista de sugestões para escolher em vez de digitar.</li><li><b>Observações prontas:</b> frases que você usa sempre e aparecem para escolher na coluna M (Observação).</li></ul></div>`,
mod:`<div class="expl"><b>Para que serve esta aba</b><p>Define o <b>formato do arquivo</b> que vai para o sistema onde você vai importar as peças (Jueri, Bling…). Cada sistema pede os nomes e a ordem das colunas de um jeito.</p><ul><li><b>Cabeçalhos, ordem e colunas:</b> valem para o arquivo baixado (.xlsx ou .csv) e para o “Copiar para o Excel”.</li><li><b>Mapeamento:</b> liga cada coluna do sistema à coluna correspondente do ERP. Coluna desligada não sai no arquivo.</li><li><b>Trocar de modelo</b> em “Exportar para”, no topo, muda a saída sem mexer nas suas peças.</li></ul></div>`,
rom:`<div class="expl"><b>Para que serve esta aba</b><p>Ensina o sistema a <b>ler a lista de compra (romaneio) de cada fornecedor</b>. Cada fornecedor monta a lista de um jeito; aqui você diz onde cada informação está.</p><ul><li><b>Modelo de leitura:</b> diz onde estão código, descrição, quantidade e preço no texto ou PDF que você cola.</li><li><b>Palavras → categoria:</b> se a descrição tem a palavra “brinco”, a peça entra na categoria Brincos (e na subcategoria que você definir). Vão para as colunas I e J.</li><li>O que o modelo lê vira <b>cartões</b> no romaneio, e cada cartão vira uma ou mais linhas da planilha.</li></ul></div>`,
roml:`<div class="expl"><b>Para que serve esta aba</b><p>O <b>histórico</b> dos romaneios que você já importou.</p><ul><li><b>Observação (documento):</b> mostra o nome do arquivo importado.</li><li><b>Abrir:</b> reabre o romaneio para lançar o que faltou ou corrigir peças já lançadas. O código da peça fica o mesmo; só muda se você trocar a categoria.</li><li><b>Excluir:</b> apaga só o romaneio guardado. As peças que você já lançou na tabela continuam lá.</li></ul></div>`,
foto:`<div class="expl"><b>Para que serve esta aba</b><p>Envia as fotos das peças para um serviço de imagens na internet e guarda o <b>link</b>.</p><ul><li>O <b>link</b> vai para a coluna B (Foto) da planilha, porque os ERPs pedem o endereço da imagem, e não o arquivo.</li><li>A foto original do romaneio fica guardada à parte (coluna “Foto do romaneio”).</li><li>A <b>chave</b> do serviço fica só neste navegador e não entra no backup.</li></ul></div>`,
opc:`<div class="expl"><b>Para que serve esta aba</b><p>Traz <b>dados antigos</b> para o sistema e cuida da <b>segurança</b> do que você já fez.</p><ul><li><b>Importar planilha:</b> lê uma planilha que você já tinha, acerta a última peça de cada prefixo (a numeração continua dali) e traz fornecedores, categorias e cores.</li><li><b>Ordem das linhas:</b> define como a planilha é montada (A depois B, ou na ordem em que você lançou).</li><li><b>Backup e pontos de restauração:</b> guardam tudo (peças, cadastros, romaneios e fotos) para você voltar no tempo se algo der errado. Faça backup com frequência: os dados ficam só neste navegador.</li></ul></div>`};

function sec(id,titulo,resumo,corpo){SECS.push({id,titulo,resumo,corpo});return ""}
function abaCfg(){return SECS.some(s=>s.id===abertos.tab)?abertos.tab:SECS[0].id}
/* ===== Catálogo rápido: colar lista, modelos, duplicar seguro, renomear e ordenar ===== */
let renBusy=false,faixaBusy=false;
let catUI={colar:false,txt:"",dup:null,ren:null,corNova:null};
const partir=txt=>{const vistos=new Set(),r=[];String(txt==null?"":txt).split(/[;,\n\r]+/).forEach(x=>{x=x.replace(/\s+/g," ").trim().slice(0,60);const k=semAc(x);if(x&&!vistos.has(k)){vistos.add(k);r.push(x)}});return r};
const kSub=x=>semAc(x).replace(/(e?s)$/,"");
const addUnicos=(lista,itens)=>{let n=0;itens.forEach(x=>{if(!lista.some(y=>kSub(y)===kSub(x))){lista.push(x);n++}});return n};
function acharCat(C,nome){const k=semAc(nome);const c=C.categorias.find(x=>semAc(x.nome)===k);if(c)return c;const j=JUERI_CATS.find(x=>(x.alias||[]).some(a=>semAc(a)===k));return j?(C.categorias.find(x=>x.nome===j.nome)||null):null}
function prefixoNovo(C,nome){const L=semAc(nome).toUpperCase().replace(/[^A-Z]/g,"");if(L.length<2)return null;const cand=[L.slice(0,2),L.slice(0,3),L.slice(0,4)];for(let j=2;j<L.length;j++)cand.push(L[0]+L[j]);const livre=cand.find(c=>!prefixoEmUso(C,c,null));return livre?{p:livre,rep:false}:{p:L.slice(0,2),rep:true}}
function nomeCatErro(C,v,exceto){if(!v)return "Digite o nome da categoria.";if(v.length>40)return "O nome da categoria é longo demais (máximo 40 letras).";if(semAc(v).replace(/[^a-z]/g,"").length<2)return "O nome da categoria precisa ter pelo menos 2 letras (o prefixo da referência sai delas). Ex.: Anéis.";if(C.categorias.some(x=>x!==exceto&&semAc(x.nome)===semAc(v)))return `Já existe a categoria “${v}” (acento e maiúscula não diferenciam).`;return ""}
function nomeCatLivre(C,base){let n=base,k=2;while(C.categorias.some(x=>semAc(x.nome)===semAc(n)))n=base+" "+(k++);return n}
const MODELOS_CAT=[
 {id:"aneis",nome:"Anéis (com tamanhos)",linha:"Anéis",grade:true},
 {id:"colares",nome:"Colares",linha:"Colares: Corrente; Gargantilha; Choker; Longo; Pingente"},
 {id:"brincos",nome:"Brincos",linha:"Brincos: Argola; Ear cuff; Pequeno; Médio; Grande"},
 {id:"pulseiras",nome:"Pulseiras",linha:"Pulseiras: Bracelete; Corrente; Riviera; Elos"},
 {id:"conjuntos",nome:"Conjuntos",linha:"Conjuntos: Colar e brinco; Brinco e anel; Completo"}];
/* lê "Anéis: Solitário; Aparador" (uma categoria por linha) e diz o que seria criado, sem mexer em nada */
function planoLista(C,txt){const tmp={categorias:[...C.categorias]},novas=[],extra=[],erros=[];
  const todas=String(txt||"").split(/\r?\n/);if(todas.length>300)erros.push(`A lista tem ${todas.length} linhas: só as 300 primeiras serão lidas.`);
  todas.slice(0,300).forEach(ln=>{ln=ln.trim();if(!ln)return;const i=ln.indexOf(":"),nome=(i<0?ln:ln.slice(0,i)).replace(/\s+/g," ").trim(),subs=i<0?[]:partir(ln.slice(i+1));
    const nv=novas.find(n=>semAc(n.nome)===semAc(nome));if(nv){addUnicos(nv.subs,subs);return}
    const ex=acharCat(C,nome);
    if(ex){let e=extra.find(x=>x.c===ex);if(!e)extra.push(e={c:ex,add:[]});subs.forEach(sb=>{if(!ex.subs.some(y=>kSub(y)===kSub(sb))&&!e.add.some(y=>kSub(y)===kSub(sb)))e.add.push(sb)});return}
    const er=nomeCatErro(tmp,nome,null);if(er){erros.push(`“${nome.slice(0,40)}”: ${er}`);return}
    const pf=prefixoNovo(tmp,nome);novas.push({nome,prefixo:pf.p,rep:pf.rep,subs:subs.slice()});tmp.categorias.push({nome,prefixo:pf.p,subs:[]})});
  return{novas,extra:extra.filter(e=>e.add.length),erros}}
const contaPlano=pl=>[pl.novas.length,pl.novas.reduce((a,n)=>a+n.subs.length,0)+pl.extra.reduce((a,e)=>a+e.add.length,0)];
function aplicaPlano(C,pl){pl.novas.forEach(n=>{C.categorias.push({nome:n.nome,prefixo:n.prefixo,subs:n.subs.slice()});if(!(n.prefixo in C.seqs))C.seqs[n.prefixo]="0"});pl.extra.forEach(e=>addUnicos(e.c.subs,e.add))}
function previaInfo(C){const tx=String(catUI.txt||"");
  if(!tx.trim())return{html:`<span class="hint">Cole ou digite uma categoria por linha. As subcategorias vêm depois dos dois-pontos, separadas por ponto e vírgula.</span>`,ok:false};
  const pl=planoLista(C,tx),[nc,ns]=contaPlano(pl);let h="";
  h+=(nc||ns)?`<b>Vai ${nc?`criar ${nc} categoria${nc>1?"s":""}${ns?" e ":"."}`:"acrescentar "}${ns?`${ns} subcategoria${ns>1?"s":""}.`:""}</b>`:`<b>Nada novo para criar</b> — tudo isso já está cadastrado.`;
  const li=[];pl.novas.forEach(n=>li.push(`<li><b>${esc(n.nome)}</b> <span class="mono">${esc(n.prefixo)}</span>${n.rep?` <span class="warn">prefixo repetido: divide a numeração com outra categoria</span>`:""}${n.subs.length?" — "+esc(n.subs.join(", ")):""}</li>`));
  pl.extra.forEach(e=>li.push(`<li><b>${esc(e.c.nome)}</b> já existe: entram só ${esc(e.add.join(", "))}</li>`));
  pl.erros.forEach(m=>li.push(`<li class="bad">${esc(m)}</li>`));
  if(li.length)h+=`<ul>${li.slice(0,15).join("")}${li.length>15?`<li>…e mais ${li.length-15}</li>`:""}</ul>`;
  return{html:h,ok:!!(nc||ns)}}
function atualizaPrevia(){const p=document.getElementById("colarPrev"),b=document.getElementById("colarOk");if(!p)return;const r=previaInfo(cfg());p.innerHTML=r.html;if(b)b.disabled=!r.ok}
function catTopo(C){
  const banner=(!abertos.catBanner&&!C.categorias.some(c=>!JUERI_CATS.some(j=>j.nome===c.nome)))?`<div class="banner" role="note"><b>Primeira vez aqui?</b><span>Monte o seu catálogo de uma vez: cole a lista de categorias e subcategorias ou comece por um modelo pronto.</span><button type="button" class="btn pri sm" data-act="colar-abrir">Montar meu catálogo</button><button type="button" class="x" data-act="banner-fechar" aria-label="Fechar esta faixa" title="Fechar">×</button></div>`:"";
  const mod=`<details class="mdl"><summary class="btn sm" title="Cria categorias e subcategorias comuns de joalheria; só entra o que ainda não existe">Começar com um modelo</summary><div class="row">${MODELOS_CAT.map(m=>`<button type="button" class="btn sm" data-act="modelo-add" data-m="${m.id}">${esc(m.nome)}</button>`).join("")}<button type="button" class="btn sm pri" data-act="modelo-add" data-m="todos">Todos</button></div><div class="hint">Só entra o que ainda não existe — nada do que você já cadastrou muda.</div></details>`;
  let painel="";
  if(catUI.colar){const r=previaInfo(C);
    painel=`<div class="cpanel" id="colarPanel"><b>Colar lista de categorias</b><span class="hint">Uma categoria por linha, assim: <span class="mono">Anéis: Solitário; Aparador; Meia aliança</span>. Se a categoria já existe, só entram as subcategorias que faltam.</span><textarea id="colarTx" data-colar aria-label="Lista de categorias e subcategorias" placeholder="Anéis: Solitário; Aparador; Meia aliança&#10;Colares: Corrente; Choker">${esc(catUI.txt)}</textarea><div id="colarPrev" class="prev" aria-live="polite">${r.html}</div><div class="row"><button type="button" class="btn pri sm" id="colarOk" data-act="colar-ok" ${r.ok?"":"disabled"}>Criar</button><button type="button" class="btn ghost sm" data-act="colar-fechar">Cancelar</button></div></div>`}
  return banner+`<div class="row"><button type="button" class="btn sm${catUI.colar?" pri":""}" data-act="${catUI.colar?"colar-fechar":"colar-abrir"}" aria-expanded="${catUI.colar?"true":"false"}" title="Cria várias categorias e subcategorias de uma vez a partir de uma lista">Colar lista</button>${mod}</div>`+painel}
/* duplicar categoria com cuidado: nome, prefixo livre e o que copiar */
function dupAviso(C,d){const p=String(d.pre||"").toUpperCase();if(!p)return "Escolha um prefixo de 1 a 4 letras.";
  const com=C.categorias.filter(x=>String(x.prefixo||"").toUpperCase()===p||Object.values(x.subPref||{}).some(v=>String(v).toUpperCase()===p)).map(x=>x.nome);
  return com.length?`O prefixo ${p} já é de ${com.join(", ")}: a cópia vai dividir a mesma numeração (continua de ${p}${ultimo(p)}). Troque o prefixo se não quiser.`:""}
function dupPainel(C,c){const d=catUI.dup,av=dupAviso(C,d);
  return `<div class="cpanel" data-dup><b>Duplicar “${esc(c.nome)}”</b><div class="row"><label class="fl" style="flex:1 1 160px"><span>Nome da nova categoria</span><input data-dup="nome" value="${esc(d.nome)}" maxlength="40"></label><label class="fl" style="width:84px"><span>Prefixo</span><input data-dup="pre" value="${esc(d.pre)}" maxlength="4" style="text-transform:uppercase" title="1 a 4 letras. Sugerido: um prefixo que ninguém usa ainda"></label></div>
  <label class="vchk"><input type="checkbox" data-dup="subs" ${d.subs?"checked":""}> Copiar as subcategorias</label><label class="vchk"><input type="checkbox" data-dup="grade" ${d.grade?"checked":""}> Copiar a variação (tamanhos, letras…)</label>
  <div class="hint">Os prefixos próprios das subcategorias não são copiados.</div><div class="soft" id="dupAviso" role="status" ${av?"":"hidden"}>${esc(av)}</div>
  <div class="row"><button type="button" class="btn pri sm" data-act="cat-dup-ok">Criar cópia</button><button type="button" class="btn ghost sm" data-act="cat-dup-no">Cancelar</button></div></div>`}
function dupAbrir(ci){const C=cfg(),c=C.categorias[ci];if(!c)return;const nome=nomeCatLivre(C,c.nome.slice(0,30)+" (cópia)"),pf=prefixoNovo(C,nome);
  catUI.dup={i:ci,nome,pre:pf?pf.p:"",preManual:false,subs:true,grade:true};renderCfg();const el=document.querySelector(`[data-cat="${ci}"] [data-dup="nome"]`);if(el){el.focus();el.select()}}
function dupCampo(t){const d=catUI.dup;if(!d)return;const k=t.dataset.dup,C=cfg();
  if(k==="nome"){d.nome=t.value;if(!d.preManual){const pf=prefixoNovo(C,d.nome);d.pre=pf?pf.p:"";const pi=document.querySelector('[data-dup="pre"]');if(pi)pi.value=d.pre}}
  else if(k==="pre"){d.pre=t.value.toUpperCase().replace(/[^A-Z]/g,"").slice(0,4);t.value=d.pre;d.preManual=true}
  else d[k]=t.checked;
  const a=document.getElementById("dupAviso");if(a){const m=dupAviso(C,d);a.textContent=m;a.hidden=!m}}
function dupOk(){const C=cfg(),d=catUI.dup;if(!d)return;const c=C.categorias[d.i];if(!c){catUI.dup=null;renderCfg();return}
  const nome=String(d.nome||"").replace(/\s+/g," ").trim(),er=nomeCatErro(C,nome,null);if(er){toast(er);const el=document.querySelector('[data-dup="nome"]');if(el)el.focus();return}
  const pre=String(d.pre||"").toUpperCase().replace(/[^A-Z]/g,"").slice(0,4);if(!pre){toast("O prefixo precisa ter de 1 a 4 letras.");const el=document.querySelector('[data-dup="pre"]');if(el)el.focus();return}
  const av=dupAviso(C,{pre}),n=clone(c);n.nome=nome;n.prefixo=pre;delete n.subPref;
  if(!d.subs){n.subs=[];delete n.subSoRef}
  if(!d.grade)delete n.grade;else if(n.grade){n.grade.id=uid();if(Array.isArray(n.grade.itens))n.grade.itens.forEach(x=>{x.id=uid()});if(n.grade.subs&&!d.subs)n.grade.subs=[]}
  C.categorias.splice(d.i+1,0,n);if(!(pre in C.seqs))C.seqs[pre]="0";catUI.dup=null;salvar(true,false);render();
  toast(`Categoria “${nome}” criada com o prefixo ${pre}.${av?" "+av:""}`,{t:"Desfazer",fn:desfazer});refocar(`[data-cat="${d.i+1}"] [data-enter="sub"]`)}
function focoChip(ci,j){const el=document.querySelectorAll(`[data-cat="${ci}"] .chip .cn`)[j];if(el)el.focus()}
function subRenomear(ci,j,novo){if(renBusy)return;renBusy=true;try{subRenomear0(ci,j,novo)}finally{renBusy=false}}
function subRenomear0(ci,j,novo){const C=cfg(),c=C.categorias[ci];catUI.ren=null;if(!c||j>=c.subs.length){renderCfg();return}
  const old=c.subs[j];novo=String(novo||"").replace(/\s+/g," ").trim();
  if(!novo||novo===old){renderCfg();return}
  if(novo.length>60){toast("O nome da subcategoria é longo demais (máximo 60 letras).");renderCfg();return}
  if(c.subs.some((x,k)=>k!==j&&semAc(x)===semAc(novo))){toast(`Já existe a subcategoria “${novo}” em ${c.nome}.`);renderCfg();return}
  c.subs[j]=novo;
  const mv=o=>{if(o&&Object.prototype.hasOwnProperty.call(o,old)){o[novo]=o[old];delete o[old]}};mv(c.subPref);mv(c.subSoRef);mv(c.subPalavra);mv(c.subAlias);mv(c.bancoPalavras);
  if(c.grade&&Array.isArray(c.grade.subs))c.grade.subs=c.grade.subs.map(x=>x===old?novo:x);
  if(c.coresCfg&&Array.isArray(c.coresCfg.subs))c.coresCfg.subs=c.coresCfg.subs.map(x=>x===old?novo:x);
  let n=0;S.lanc.forEach(l=>{if(l.v&&l.v.I===c.nome&&l.v.J===old){l.v.J=novo;n++}});
  if(S.form&&S.form.v&&S.form.v.I===c.nome&&S.form.v.J===old)S.form.v.J=novo;
  (C.romaneios||[]).forEach(T=>{if(T&&T.mapa)T.mapa=String(T.mapa).split(";").map(it=>{const q=it.indexOf("=");if(q<0)return it;return it.slice(q+1).trim()===c.nome+">"+old?it.slice(0,q+1)+c.nome+">"+novo:it}).join(";")});
  if(rascunho&&rascunho.v&&rascunho.v.I===c.nome&&rascunho.v.J===old)rascunho.v.J=novo;
  sincGrade(S.form);salvar(true,n>0);render();
  toast(`Subcategoria “${old}” agora é “${novo}”.${n?` ${n} peça(s) já lançadas foram atualizadas.`:""}`,{t:"Desfazer",fn:desfazer})}
/* banhos prontos */
const BANHOS_PRONTOS={ouro:{nome:"Ouro",cor:"Ouro",coluna:"R",sufixo:" banho ouro"},rodio:{nome:"Ródio",cor:"Ródio",coluna:"S",sufixo:" banho ródio"},prata:{nome:"Prata",cor:"Prata",coluna:"T",sufixo:" banho prata"},negro:{nome:"Ródio negro",cor:"Ródio negro",coluna:"S",sufixo:" banho ródio negro"},outro:{nome:"Novo banho",cor:"",coluna:"S",sufixo:""}};
function letraBanhoLivre(b){const us=b.banhos.map(x=>String(x.letra||"").trim().toUpperCase());for(let k=0;k<26;k++){const L=String.fromCharCode(65+k);if(!us.includes(L))return L}return ""}
function nomeBanhoLivre(b,base){const raiz=String(base||"Banho").replace(/\s+\d+$/,"").trim()||"Banho";let n=raiz,k=2;while(b.banhos.some(x=>semAc(x.nome)===semAc(n)))n=raiz+" "+(k++);return n}
function corOpts(C,x){const falta=x.cor&&!C.cores.includes(x.cor);
  return (falta?`<option value="${esc(x.cor)}" selected>⚠ ${esc(x.cor)} (não está em Cores)</option>`:"")+`<option value="" ${!x.cor?"selected":""}>— sem cor —</option>`+opts(C.cores,x.cor)+`<option value="__nova">+ Nova cor…</option>`}
function corNovaOk(){const C=cfg(),cn=catUI.corNova;if(!cn)return;const inp=document.querySelector("[data-ncor]"),nome=String(inp?inp.value:"").replace(/[;,]+/g," ").replace(/\s+/g," ").trim().slice(0,40);
  if(!nome){toast("Digite o nome da cor.");if(inp)inp.focus();return}
  const b=C.banhistas[cn.bi],bn=b&&b.banhos[cn.j];if(!bn){catUI.corNova=null;renderCfg();return}
  let cor=C.cores.find(c=>semAc(c)===semAc(nome));if(!cor){cor=nome;C.cores.push(cor)}
  bn.cor=cor;catUI.corNova=null;salvar(true,false);render();toast(`Cor “${cor}” pronta e escolhida para o banho ${bn.nome}.`,{t:"Desfazer",fn:desfazer});refocar(`[data-bh="${cn.bi}"] [data-bn="${cn.j}"] [data-bnf="cor"]`)}
/* Categorias: cada cartão traz prefixo, última peça, subcategorias, variação (tamanhos/letras) e a exclusão */
function secCat(C,usoPref){const topo=catTopo(C);
  const comGrade=C.categorias.filter(x=>x.grade).map(x=>x.nome);
  const colOpts=g=>opts(LET.filter(L=>!["E","F"].includes(L)).map(L=>[L,NOME[L]]),g.col||"","(nenhuma)");
  const gradeEd=(g,key,ok,delBtn)=>`<details class="gdet" data-open="${esc(ok)}" ${abertos[ok]?"open":""} data-gr="${key}"><summary><b>Variação · ${esc(g.nome)}</b><span>${esc(g.itens.map(x=>x.letra+" "+(x.nome||"")).join(", ")||"sem opções")}${(g.subs||[]).length?` · só em ${esc(g.subs.join(", "))}`:""}</span></summary>
      <div class="gb"><div class="row">
        <label class="fl" style="flex:1 1 120px"><span>Nome da variação</span><input data-gf="nome" value="${esc(g.nome)}"></label>
        <label class="fl" style="width:104px"><span>Texto antes do nome</span><input data-gf="rotulo" value="${esc(g.rotulo||"")}" placeholder="ex.:  aro " title="Ex.: ' aro ' ou ' tamanho ' — vale para todas as opções e também troca o termo já digitado na Descrição"></label>
        <label class="fl" style="width:140px"><span>Coluna do valor</span><select data-gf="col">${colOpts(g)}</select></label>
        <label class="fl" style="width:130px"><span>Opções que vêm marcadas</span><input data-gf="faixa" value="${esc(g.faixa||"")}" placeholder="ex.: 12, 14, 16" title="Ao escolher a categoria no lançamento, estas opções já vêm marcadas. Também aceita faixa: 12-16 ou 12 a 16"></label>
        <label class="fl" style="width:150px"><span>Na referência usar</span><select data-gf="modoRef" title="Letra: AN6AA, AN6BA (banho + letra da opção). Nome: AN6A12 (banho + nome da opção)">${opts([["letra","Letra (AA, BA…)"],["nome","Nome (A12…)"]],g.modoRef||"letra")}</select></label>
        <label class="fl" style="flex:1 1 150px"><span>Só nestas subcategorias</span><input data-gf="subs" value="${esc((g.subs||[]).join("; "))}" placeholder="vazio = toda a categoria" title="Separe por ; — ex.: Anéis"></label>
        ${delBtn}</div>
      <div class="tw"><table class="cfg bnt"><thead><tr><th>Letra</th><th>Nome no lançamento</th><th>Texto na Descrição (da opção)</th><th>Coluna</th><th>Valor</th><th></th></tr></thead><tbody>
      ${g.itens.map((x,j)=>`<tr data-gii="${j}"><td data-th="Letra"><input data-gif="letra" value="${esc(x.letra)}" maxlength="2" style="width:42px;text-transform:uppercase" aria-label="Letra da opção ${esc(x.nome||x.letra)}"></td><td data-th="Nome no lançamento"><input data-gif="nome" value="${esc(x.nome||"")}" style="width:100px" aria-label="Nome da opção ${esc(x.nome||x.letra)}"></td>
        <td data-th="Texto na Descrição (da opção)"><input data-gif="texto" aria-label="Texto na Descrição da opção ${esc(x.nome||x.letra)}" value="${esc(x.texto||"")}" placeholder="${esc(efetivo(g,x).texto)}" style="width:130px" title="Vazio = segue a variação: ${esc(efetivo(g,x).texto)}"></td><td data-th="Coluna"><select data-gif="col" aria-label="Coluna da opção ${esc(x.nome||x.letra)}" style="width:140px">${opts(LET.filter(L=>!["E","F"].includes(L)).map(L=>[L,NOME[L]]),x.col||"","(igual à variação)")}</select></td>
        <td data-th="Valor"><input data-gif="valor" aria-label="Valor da opção ${esc(x.nome||x.letra)}" value="${esc(x.valor||"")}" placeholder="${esc(efetivo(g,x).valor)}" style="width:80px" title="Vazio = o nome da opção"></td><td class="acts" data-th=""><button class="x" type="button" data-act="gi-del" title="Remover opção" aria-label="Remover a opção ${esc(x.nome||x.letra)}">×</button></td></tr>`).join("")}
      </tbody></table></div>
      <div class="row"><input data-enter="gi" aria-label="Novas opções da variação" placeholder="+ Opções, Enter (ex.: 24; 26; 28)" style="max-width:260px"><span class="hint">Deixe Texto, Coluna e Valor em branco para seguir a variação: o que mudar em cima muda em todas as opções. A Descrição recebe “${esc(rotG(g))}nome” e a coluna ${esc(g.col?NOME[g.col]:"—")} recebe o nome.</span></div></div></details>`;
  const gradeUI=(c,i)=>{const g=c.grade;
    if(g&&(g.usa||g.usaId))return `<div class="row gnone" data-gr="${i}"><span class="hint">Usa a mesma variação de <b>${esc(g.usa||((C.grades||[]).find(x=>x.id===g.usaId)||{}).nome||"?")}</b> — mude lá e vale aqui também.</span><label class="fl" style="flex:1 1 150px"><span>Só nestas subcategorias</span><input data-gf="subs" value="${esc((g.subs||[]).join("; "))}" placeholder="vazio = toda a categoria"></label><button class="btn sm" type="button" data-act="gr-own">Ter variação própria</button><button class="x" type="button" data-act="gr-del" title="Remover a variação desta categoria" aria-label="Remover a variação desta categoria">×</button></div>`;
    if(!g)return `<div class="row gnone"><button class="btn sm" type="button" data-act="gr-add" title="Variação: tamanhos, letras ou qualquer opção que gere uma linha por escolha">＋ Variação (tamanhos, letras…)</button>${comGrade.length||(C.grades||[]).length?`<select data-gcp aria-label="Usar uma variação já cadastrada" style="width:auto"><option value="">ou usar a variação de…</option>${comGrade.map(n=>`<option>${esc(n)}</option>`).join("")}${(C.grades||[]).map(g=>`<option value="o:${esc(g.id)}">${esc(g.nome)}</option>`).join("")}</select>`:""}</div>`;
    return `<div class="row gnone" data-gr="${i}"><span class="hint">Variação própria: <b>${esc(g.nome)}</b> · ${esc(g.itens.map(x=>x.nome||x.letra).join(", ")||"sem opções")}</span><button class="btn sm" type="button" data-act="ir" data-sec="cor">Editar em Cores, tamanhos e variações</button><label class="fl" style="flex:1 1 150px"><span>Só nestas subcategorias</span><input data-gf="subs" value="${esc((g.subs||[]).join("; "))}" placeholder="vazio = toda a categoria"></label><button class="x" type="button" data-act="gr-del" title="Remover a variação desta categoria" aria-label="Remover a variação desta categoria">×</button></div>`};
  const coresUI=(c,i)=>{const cf=c.coresCfg||{},pad=coresDaCat(c.nome).filter(x=>(cf.padrao||[]).includes(x.id)).map(x=>x.nome).join("; ");return `<details class="gdet" data-open="cv:${esc(c.nome)}" ${abertos["cv:"+c.nome]?"open":""}><summary><b>Cor da pedra · ajustes desta categoria</b><span>${pad?"vêm marcadas: "+esc(pad):"as cores vêm da aba Cores, tamanhos e variações"}</span></summary><div class="gb"><div class="row"><label class="fl" style="flex:1 1 160px"><span>Só nestas subcategorias</span><input data-cvg="subs" value="${esc((cf.subs||[]).join("; "))}" placeholder="vazio = toda a categoria" title="Separe por ; — ex.: Anéis"></label><label class="fl" style="flex:1 1 160px"><span>Cores que vêm marcadas</span><input data-cvg="padrao" value="${esc(pad)}" placeholder="ex.: Dourado; Prata" title="Ao escolher a categoria no lançamento, estas cores já vêm marcadas"></label><label class="fl" style="width:160px"><span>Na referência usar</span><select data-cvg="modoRef" title="Letra: usa a sigla de cada cor. Nome: usa o nome da cor inteiro">${opts([["letra","Sigla da cor"],["nome","Nome da cor"]],cf.modoRef||"letra")}</select></label><label class="fl" style="width:190px"><span>Enviar o nome da cor para a coluna</span><select data-cvg="col" title="Se escolher uma coluna, o nome da cor também vai para ela (ex.: Cor, para o Bling criar a variação por cor)">${opts(LET.filter(L=>!["E","F"].includes(L)).map(L=>[L,NOME[L]]),cf.col||"","(só na descrição)")}</select></label></div><div class="hint"><b>Não é a cor do banho</b> (Ouro, Prata, Ródio): é a cor da pedra ou do detalhe. As cores e as siglas são cadastradas na aba <b>Cores, tamanhos e variações</b>; ao lançar, use o botão <b>＋ Cor da pedra</b>.</div></div></details>`};
  const card=(c,i)=>{const p=(c.prefixo||"").toUpperCase(),outras=(usoPref[p]||[]).filter(n=>n!==c.nome),nUsos=S.lanc.filter(l=>val(l,"I")===c.nome).length;
    const del=delCat===c.nome?`<span class="cdel">Excluir “${esc(c.nome)}”?${nUsos?` As ${nUsos} peça(s) já lançadas continuam com este nome.`:""} <button class="btn danger sm" type="button" data-act="cat-del-ok">Sim, excluir</button><button class="btn sm" type="button" data-act="cat-del-no">Não</button></span>`:`<button class="btn ghost danger sm" type="button" data-act="cat-del" title="Excluir esta categoria">Excluir categoria</button>`;
    return `<div class="card" data-cat="${i}">
      <div class="row"><label class="fl" style="flex:1 1 120px"><span>Categoria</span><input data-cf="nome" value="${esc(c.nome)}"></label><label class="fl" style="width:60px"><span>Prefixo</span><input data-cf="prefixo" value="${esc(c.prefixo)}" style="text-transform:uppercase"></label>
      <label class="fl" style="width:84px"><span>Última peça</span><input class="n" data-cf="ultimo" value="${esc(C.seqs[p]||"")}" inputmode="numeric"></label>
      <label class="fl" style="width:130px"><span>Palavra na descrição</span><input data-cf="palavra" value="${esc(c.palavra!=null?c.palavra:"")}" placeholder="${esc(palavraDeNome(c.nome))}" title="Palavra que aparece acima da descrição para começar a escrever (ex.: Brinco). Vazio = deduzida do nome; - (traço) = nenhuma."></label>
      <label class="fl" style="width:150px"><span>Nome na planilha</span><input data-cf="nomeExport" value="${esc(c.nomeExport||"")}" placeholder="${esc(c.nome)}" title="Como esta categoria sai no arquivo exportado, se o outro sistema (ex.: Jueri) a conhece com outro nome. Vazio = o próprio nome."></label>
      <label class="fl" style="width:190px"><span>Apelidos (digitação rápida)</span><input data-cf="apelidos" value="${esc(c.apelidos||"")}" placeholder="ex.: brinco; brincos" title="Outros nomes que você digita no campo Categoria e que viram esta categoria sozinhos. Separe com ponto e vírgula."></label>
      <label class="fl" style="width:210px"><span>Texto da categoria na Descrição</span><input data-cf="sufixo" value="${esc(c.sufixo||"")}" placeholder="(nada)" title="Frase escrita sozinha no fim da descrição de toda peça desta categoria. Ex.: texto “Prata 925” + peça “Argola lisa” = “Argola lisa Prata 925”. Não repete se a descrição já tiver o texto. Vazio = não acrescenta nada."></label>
      <span class="dh" draggable="true" data-dk="cat" data-di="${i}" title="Arraste para mudar a ordem das categorias" aria-label="Arrastar a categoria ${esc(c.nome)}">⠿</span><button class="x" type="button" data-act="cat-up" ${i===0?"disabled":""} title="Subir esta categoria" aria-label="Subir a categoria ${esc(c.nome)}">↑</button><button class="x" type="button" data-act="cat-down" ${i===C.categorias.length-1?"disabled":""} title="Descer esta categoria" aria-label="Descer a categoria ${esc(c.nome)}">↓</button><button class="x" type="button" data-act="cat-dup" title="Duplicar esta categoria" aria-label="Duplicar a categoria ${esc(c.nome)}">⧉</button></div>${catUI.dup&&catUI.dup.i===i?dupPainel(C,c):""}
      <div class="clbl">Fiscal e insumos <span>vazio = usa o padrão da coluna</span></div><div class="row fisc"><label class="fl" style="width:96px"><span>NCM</span><input data-cf="ncm" value="${esc(c.ncm||"")}" placeholder="${esc(C.colcfg.Y.padrao||"padrão")}"></label><label class="fl" style="width:64px"><span>CFOP</span><input data-cf="cfop" value="${esc(c.cfop||"")}" placeholder="${esc(C.colcfg.AA.padrao||"")}"></label><label class="fl" style="width:56px"><span>FCP</span><input data-cf="fcp" value="${esc(c.fcp||"")}" placeholder="${esc(C.colcfg.AB.padrao||"")}"></label><label class="fl" style="width:84px"><span>Insumos</span><input class="n" data-cf="insumos" value="${esc(c.insumos||"")}" placeholder="${esc(C.colcfg.Q.padrao||"")}" title="Custo de Insumos desta categoria"></label></div>
      <div class="clbl">Venda por grama, sem banho <span>ex.: Prata 925 — o custo de compra é peso × valor do grama</span></div><div class="row fisc"><label class="vchk" title="Peça sem galvânica: entra como Pronta, sem colunas de banho, verniz nem milésimos, e a referência não ganha letra de banho"><input type="checkbox" data-cf="semBanho" ${c.semBanho?"checked":""}> Sem banho (sem galvânica, verniz nem milésimos)</label><label class="fl" style="width:150px"><span>Compra por grama (R$/g)</span><input class="n" data-cf="compraGrama" value="${esc(c.compraGrama||"")}" inputmode="decimal" placeholder="digitar o custo" title="Preenche o Custo de Compra sozinho: peso × este valor. Vazio = você digita o custo de cada peça."></label></div>
      <div class="hint">Próxima <b class="mono">${esc(p)}${fnum(p,ultimo(p)+1)}</b>${outras.length?` · sequência dividida com ${esc(outras.join(", "))}`:""}</div>
      <div class="clbl">Subcategorias <span>clique no nome para renomear · a caixinha ao lado é o prefixo próprio</span>${c.subs.length>1?`<button class="btn ghost sm" type="button" data-act="sub-az" title="Ordenar as subcategorias de A a Z">A–Z</button>`:""}</div><div class="chips">${c.subs.map((s,j)=>`<span class="chip">${j>0?`<button type="button" class="mv" data-act="sub-up" data-j="${j}" aria-label="Mover ${esc(s)} para antes" title="Mover para antes">‹</button>`:""}${catUI.ren&&catUI.ren.i===i&&catUI.ren.j===j?`<input class="cn-in" data-subren="${j}" value="${esc(s)}" maxlength="60" aria-label="Novo nome da subcategoria ${esc(s)}">`:`<button type="button" class="cn" data-act="sub-ren" data-j="${j}" title="Clique para renomear" aria-label="Renomear ${esc(s)}">${esc(s)}</button>`}<input class="sp" data-sp="${esc(s)}" value="${esc((c.subPref||{})[s]||"")}" placeholder="${esc(p)}" title="Prefixo próprio desta subcategoria (vazio = ${esc(p)})" aria-label="Prefixo de ${esc(s)}"><input class="sw" data-sw="${esc(s)}" value="${esc(((c.subPalavra||{})[s])!=null?c.subPalavra[s]:"")}" placeholder="${esc(palavraDeNome(s))}" title="Palavra desta subcategoria para a descrição (ex.: Argola). Vazio = deduzida do nome; - = nenhuma." aria-label="Palavra de ${esc(s)} na descrição"><input class="sa" data-sa="${esc(s)}" value="${esc((c.subAlias||{})[s]||"")}" placeholder="apelidos" title="Outros nomes que você digita e que escolhem esta subcategoria (e a categoria) sozinhos. Ex.: argolinhas; argola" aria-label="Apelidos de ${esc(s)}"><label class="sr" title="Marcada: a subcategoria serve só para escolher o prefixo da referência e não vai para a planilha (a categoria não tem essa subcategoria no Jueri)"><input type="checkbox" data-sr="${esc(s)}" ${(c.subSoRef||{})[s]?"checked":""}>só para a referência</label>${j<c.subs.length-1?`<button type="button" class="mv" data-act="sub-down" data-j="${j}" aria-label="Mover ${esc(s)} para depois" title="Mover para depois">›</button>`:""}<button type="button" data-act="sub-del" data-j="${j}" aria-label="Remover ${esc(s)}">×</button></span>`).join("")}<input data-enter="sub" placeholder="+ Subcategoria, Enter (várias: use ;)" aria-label="Nova subcategoria de ${esc(c.nome)}"></div>${c.subs.length?"":`<div class="soft">Esta categoria ainda não tem subcategorias${c.grade?"":" nem variação (tamanhos, letras…)"}. Digite acima e aperte Enter — pode pôr várias de uma vez separadas por ;</div>`}
      ${gradeUI(c,i)}${coresUI(c,i)}
      <div class="cfoot">${del}</div></div>`};
  const usadaEm=(g,nomeCat)=>{const u=C.categorias.filter(x=>x.grade&&((nomeCat&&(x.grade.usa===nomeCat))||(g&&g.id&&x.grade.usaId===g.id))).map(x=>x.nome);if(nomeCat)u.unshift(nomeCat);return u.length?`<div class="hint">Usada em: <b>${esc(u.join(", "))}</b></div>`:`<div class="hint">Ainda não usada em nenhuma categoria: escolha-a na categoria (“ou usar a variação de…”) ou ao lançar.</div>`};
  LIBTAM=`<div class="clbl">Tamanhos e variações <span>tamanhos de anel, P M G, medidas… cada conjunto vale para qualquer categoria</span></div>
    ${C.categorias.map((c,i)=>c.grade&&!c.grade.usa&&!c.grade.usaId?`<div class="libg" data-cat="${i}">${usadaEm(null,c.nome)}${gradeEd(c.grade,i,"g:"+c.nome,`<button class="x" type="button" data-act="gr-del" title="Remover esta variação (as categorias que a usam ficam sem)" aria-label="Remover a variação">×</button>`)}</div>`:"").join("")}
    ${(C.grades||[]).map((g,k)=>`<div class="libg">${usadaEm(g,null)}${gradeEd(g,"o"+k,"go:"+k,`<button class="x" type="button" data-act="go-del" data-k="${k}" title="Excluir esta variação" aria-label="Excluir a variação">×</button>`)}</div>`).join("")}
    <div class="row"><button class="btn sm pri" type="button" data-act="lib-grade-add">＋ Nova variação</button><button class="btn sm" type="button" data-act="lib-grade-pmg" title="Cria o conjunto P, M, G">＋ P M G</button><span class="hint">Dê o nome (ex.: “Aro de anel”), digite as opções (11; 12; 13…) e escolha a coluna do valor. Depois use em qualquer categoria.</span></div>`;
  const orf=(C.grades||[]).map((g,k)=>`<div class="card" data-gr="o${k}"><div class="row"><b>Variação sem categoria: ${esc(g.nome)}</b><span class="hint">${esc(g.itens.map(x=>x.letra+" "+(x.nome||"")).join(", "))}</span><select data-gmove="${k}" style="width:auto"><option value="">Mover para a categoria…</option>${C.categorias.filter(x=>!x.grade).map(x=>`<option>${esc(x.nome)}</option>`).join("")}</select><button class="x" type="button" data-act="go-del" data-k="${k}" title="Excluir esta variação">×</button></div></div>`).join("");
  return sec("cat","Categorias",C.categorias.slice(0,4).map(c=>`${c.nome} ${(c.prefixo||"").toUpperCase()}${ultimo((c.prefixo||"").toUpperCase())}`).join(" · ")+"…",
    `<p class="d">A última peça já cadastrada no sistema define de onde a numeração continua. Categorias com o mesmo prefixo dividem a sequência (Brincos e Prata 925 usam BR). Cada subcategoria pode ter prefixo próprio: em Prata 925, Colares sai como CO e Brincos como BR. “Texto da categoria na Descrição” é acrescentado ao fim da descrição de toda peça da categoria. A <b>variação</b> (tamanhos de anel, letras…) fica dentro da categoria: ao escolher a categoria no lançamento, as opções aparecem sozinhas, e só nela.</p>${topo}<div class="row"><input id="catBusca" type="search" placeholder="Filtrar categorias…" aria-label="Filtrar categorias" style="max-width:260px"><span class="hint">${C.categorias.length} categorias</span><button class="btn ghost sm" type="button" data-act="cat-az" title="Ordenar as categorias de A a Z">Ordenar A–Z</button></div>${fiscalTodasHTML(C)}<label class="vchk" style="margin:6px 0"><input type="checkbox" data-gcfg="descAuto" ${C.descAuto===false?"":"checked"}> Ao escolher categoria e subcategoria, começar a descrição sozinho com as palavras delas (ex.: “Brinco Argola ”)</label><div class="cards">${C.categorias.map(card).join("")}</div>${orf}
    <div class="row"><input id="novaCat" aria-label="Nova categoria" placeholder="Nova categoria" style="max-width:260px"><button class="btn sm" type="button" data-act="cat-add">Adicionar categoria</button></div>`);
}
/* gráfico de rosca (SVG, sem bibliotecas) ao lado do formulário */
const PAL=["#27466f","#3f8f8b","#c28b2c","#8a5fb0","#c5584f","#6a9e4f","#5b86c9","#a0a7b4","#b5651d","#2f7d5b"];
function renderGraf(D){
  const el=document.getElementById("graf");if(!el)return;const modo=abertos.graf||"custo";
  const M={custo:["Custo por componente",D.custo,"R$ "],pecas:["Peças por categoria",Object.entries(D.pecas),""],varejo:["Varejo por categoria",Object.entries(D.varejo),"R$ "],cor:["Peças por cor",Object.entries(D.cor),""],forn:["Custo por fornecedor",Object.entries(D.forn),"R$ "],banho:["Peças por banho",Object.entries(D.banho),""],lucro:["Lucro por categoria",Object.entries(D.lucro),"R$ "]};
  const m=M[modo]||M.custo,arr=m[1].filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]),tot=arr.reduce((s,x)=>s+x[1],0),pre=m[2],f2=n=>(Math.round(n*100)/100).toFixed(2);
  let svg="";
  if(tot>0){const R=62,r=38,cx=70,cy=70;let a0=-Math.PI/2;
    arr.forEach((x,i)=>{const fr=x[1]/tot,a1=a0+fr*2*Math.PI,col=PAL[i%PAL.length],tt=`<title>${esc(x[0])}: ${pre}${pre?brl(x[1]):fmt(x[1])} (${Math.round(fr*1000)/10}%)</title>`;
      if(arr.length===1)svg+=`<circle cx="${cx}" cy="${cy}" r="${(R+r)/2}" fill="none" stroke="${col}" stroke-width="${R-r}">${tt}</circle>`;
      else{const P=(rad,a)=>[f2(cx+rad*Math.cos(a)),f2(cy+rad*Math.sin(a))],lg=fr>.5?1:0,[x0,y0]=P(R,a0),[x1,y1]=P(R,a1),[x2,y2]=P(r,a1),[x3,y3]=P(r,a0);
        svg+=`<path d="M${x0} ${y0}A${R} ${R} 0 ${lg} 1 ${x1} ${y1}L${x2} ${y2}A${r} ${r} 0 ${lg} 0 ${x3} ${y3}Z" fill="${col}" stroke="var(--surface)" stroke-width="1.5">${tt}</path>`}
      a0=a1});
    svg=`<svg viewBox="0 0 140 140" role="img" aria-label="${esc(m[0])}">${svg}<text x="70" y="66" text-anchor="middle" class="gc-l">total</text><text x="70" y="82" text-anchor="middle" class="gc-v">${pre?brl(tot):fmt(tot)}</text></svg>`}
  el.innerHTML=`<div class="gh"><b>${m[0]}</b></div><div class="gm" role="group" aria-label="Tipo de gráfico">${[["custo","Custo"],["pecas","Peças"],["varejo","Varejo"],["lucro","Lucro"],["forn","Fornec."],["banho","Banho"],["cor","Cores"]].map(([k,n])=>`<button type="button" class="${k===modo?"on":""}" data-act="graf" data-v="${k}">${n}</button>`).join("")}</div>
    ${tot>0?`<div class="gp">${svg}</div><ul class="gl">${arr.slice(0,8).map((x,i)=>`<li><i style="background:${PAL[i%PAL.length]}"></i><span>${esc(x[0])}</span><b>${pre}${pre?brl(x[1]):fmt(x[1])}</b><small>${Math.round(x[1]/tot*1000)/10}%</small><u style="width:${Math.max(2,Math.round(x[1]/arr[0][1]*100))}%;background:${PAL[i%PAL.length]}"></u></li>`).join("")}</ul>`:`<p class="hint" style="padding:14px 4px">Lance peças para ver o gráfico. ${modo==="varejo"||modo==="lucro"?"Varejo e lucro aparecem quando há Preço de Varejo ou Multiplicador.":""}</p>`}`;
}
function modPrev(m){const g=G;if(!g||!g.linhas||!g.linhas.length)return `<details class="gdet"><summary><b>Prévia do arquivo</b><span>lance uma peça para ver como a 1ª linha sai</span></summary></details>`;
  let e;try{e=saidaLinhas(g,m)[0]}catch(x){e=null}if(!e)return "";const cs=celulas(e.row,2);
  const itens=m.cols.filter(c=>c.on!==false).map(c=>{let v="";try{const r=valorCol(c,celCol(c,cs,e));v=r?(r.v==null?(r.f?"="+r.f:""):String(r.v)):""}catch(x){}return [c.h||(c.k?NOME[c.k]:"(coluna)"),v]}).filter(x=>x[1]!=="");
  return `<details class="gdet" data-open="modprev" ${abertos.modprev?"open":""}><summary><b>Prévia do arquivo</b><span>como a 1ª linha da sua tabela sai neste sistema (${itens.length} campos preenchidos)</span></summary><div class="gb"><div class="prevg">${itens.map(x=>`<div><small>${esc(x[0])}</small><b>${esc(x[1].length>60?x[1].slice(0,58)+"…":x[1])}</b></div>`).join("")}</div></div></details>`}
function secModelo(C){
  const m=modeloAtual(),chaves=[["","(em branco)"],...LET.map(L=>[L,NOME[L]]),["@desc","⚙ Descrição (variação: atributos)"],["@pv","⚙ Produto / Variação (automático)"],["@pai","⚙ Código do pai (automático)"]];
  const av=!!abertos.modAv,todas=!!abertos.modTodas,vaz=c=>!c.k&&vazio(c.padrao);let n=0;
  const nBr=m.cols.filter(c=>c.on!==false&&vaz(c)).length;
  const linhas=m.cols.map((c,i)=>{const on=c.on!==false,L=on?letraN(n++):"—";if(!todas&&on&&vaz(c))return "";
    return `<tr data-mc="${i}" class="${vaz(c)?"mc-br":""}"><td class="mono hint">${L}</td><td class="c"><input type="checkbox" data-mcf="on" ${on?"checked":""} aria-label="Usar"></td><td><input data-mcf="h" value="${esc(c.h)}" style="width:220px"></td><td><select data-mcf="k" style="width:230px">${opts(chaves,c.k||"")}</select></td><td class="adv"><select data-mcf="tipo" style="width:130px">${opts(TIPOS_COL,c.tipo||"")}</select></td><td class="adv"><input class="n" data-mcf="fator" value="${esc(c.fator||"")}" style="width:64px" inputmode="decimal" placeholder="×1" aria-label="Fator de multiplicação" title="Multiplica o número (ex.: peso em gramas × 0,001 = quilos)"></td><td class="adv c"><input type="checkbox" data-mcf="obrig" ${c.obrig?"checked":""} aria-label="Obrigatória"></td><td class="adv"><input data-mcf="padrao" value="${esc(c.padrao||"")}" style="width:110px" placeholder="(nada)" aria-label="Valor padrão"></td><td class="adv"><input class="n" data-mcf="max" value="${esc(c.max||"")}" style="width:56px" inputmode="numeric" placeholder="0" aria-label="Máximo de caracteres"></td><td class="adv"><input data-mcf="lista" value="${esc(c.lista||"")}" style="width:160px" placeholder="opção 1; opção 2" aria-label="Lista válida"></td><td style="white-space:nowrap"><button class="x" type="button" data-act="mc-up" title="Subir">↑</button><button class="x" type="button" data-act="mc-down" title="Descer">↓</button><button class="x" type="button" data-act="mc-del" title="Remover do modelo">×</button></td></tr>`}).join("");
  const avancado=av?`<div class="row"><label class="fl" style="width:230px"><span>Variações</span><select data-mod="agrupar" title="Com “produto pai + variações”, cada peça com banhos ou tamanhos vira uma linha de produto e uma linha por variação (como o Bling pede). Use com as colunas ⚙ automáticas.">${opts([["","Cada linha é um produto"],["sim","Produto pai + variações"]],m.agrupar==="sim"?"sim":"")}</select></label><label class="fl" style="width:150px"><span>Tipo de arquivo</span><select data-mod="formato">${opts([["xlsx","Planilha (.xlsx)"],["csv","Texto (.csv)"]],m.formato==="csv"?"csv":"xlsx")}</select></label>
      ${m.formato==="csv"?`<label class="fl" style="width:130px"><span>Separador</span><select data-mod="sep">${opts([[";","Ponto e vírgula ( ; )"],[",","Vírgula ( , )"],["tab","Tabulação"]],m.sep||";")}</select></label><label class="fl" style="width:120px"><span>Decimal</span><select data-mod="dec">${opts([[",","Vírgula (1,50)"],[".","Ponto (1.50)"]],m.dec||",")}</select></label><label class="fl" style="width:150px"><span>Codificação</span><select data-mod="enc">${opts([["utf8bom","UTF-8 com BOM (Excel)"],["utf8","UTF-8"]],m.enc||"utf8bom")}</select></label>`:`<label class="fl" style="width:150px"><span>Nome da aba</span><input data-mod="aba" value="${esc(m.aba||"")}" placeholder="Worksheet" maxlength="31"></label>`}
      <label class="fl" style="width:120px"><span>Máx. de linhas por arquivo</span><input class="n" data-mod="lote" value="${esc(num(m.lote)>0?m.lote:"")}" inputmode="numeric" placeholder="sem limite" title="Divide em vários arquivos, sem separar um produto pai das suas variações. O Bling aceita até 1000 por importação."></label></div>
`:"";
  return sec("mod","Exportar para",`${C.modelos.length} sistema(s) · em uso: ${esc(m.nome)}`,
    `<p class="d">Escolha o sistema no menu <b>Exportar para</b>, lá em cima: o arquivo que você baixa já sai no formato dele. Abaixo está o que cada coluna do arquivo vai receber. Para um sistema que não está na lista, use <b>＋ Outro sistema</b> e escolha a planilha modelo dele: o app monta tudo sozinho.</p>
    <div class="mod-chips" role="group" aria-label="Sistemas de destino"><b class="mod-t">Meus sistemas</b>${C.modelos.map(x=>`<button type="button" class="chipbtn${x.id===m.id?" on":""}" data-act="mod-sel" data-id="${esc(x.id)}" aria-pressed="${x.id===m.id}" title="${x.id===m.id?"Em uso":"Usar este sistema"}">${esc(x.nome)}${x.id===m.id?" ✓":""}</button>`).join("")}<button type="button" class="chipbtn novo" data-act="mod-novo" title="Monta um modelo a partir da planilha de exemplo do outro sistema">＋ Outro sistema…</button></div>
    <div class="row"><label class="fl" style="width:230px"><span>Nome deste sistema</span><input data-mod="nome" value="${esc(m.nome)}"></label>
      <button class="btn sm pri" type="button" data-act="mod-conferir" title="Confere a tabela atual com este modelo, sem exportar">Conferir a tabela</button>
      <details class="mdl"><summary class="btn sm">Mais ações</summary><div class="row"><button class="btn sm" type="button" data-act="mod-dup">Duplicar este</button><button class="btn sm danger" type="button" data-act="mod-del" ${C.modelos.length>1?"":"disabled"}>Excluir este</button><button class="btn sm" type="button" data-act="mod-salvar" title="Baixa este modelo num arquivo para guardar ou passar a outra pessoa">Salvar modelo (.json)</button><label class="btn sm" style="cursor:pointer" title="Abre um modelo salvo">Abrir modelo (.json)<input type="file" id="fileModJ" accept=".json" class="vh"></label><button class="btn sm" type="button" data-act="mod-jueri">＋ Modelo Jueri</button><button class="btn sm" type="button" data-act="mod-bling" title="As 59 colunas da planilha modelo oficial do Bling (CSV)">＋ Modelo Bling</button></div></details>
      <button class="btn sm ghost" type="button" data-act="mod-av" title="Tipo de dado, valor padrão, lista de valores, tamanho máximo, variações, CSV…">⚙ Regras avançadas ${av?"▴":"▾"}</button></div>
    ${avancado}
    ${nBr?`<div class="hint">${todas?`Mostrando todas as colunas, inclusive ${nBr} que saem em branco.`:`${nBr} coluna(s) do arquivo saem em branco (o app não tem esse dado) e estão escondidas.`} <button class="lnk" type="button" data-act="mod-brancas">${todas?"Esconder as em branco":"Mostrar também"}</button></div>`:""}
    ${modPrev(m)}
    <div class="tw"><table class="cfg ${av?"":"noadv"}"><thead><tr><th>Col.</th><th>Usar</th><th>Nome da coluna no arquivo</th><th>Vai receber</th><th class="adv" title="Como o valor sai no arquivo">Tipo</th><th class="adv" title="Multiplica o número (ex.: gramas × 0,001 = quilos)">× Fator</th><th class="adv" title="Avisa antes de exportar se estiver vazia">Obrig.</th><th class="adv" title="Entra quando a célula está vazia (ou sempre, se a coluna é “em branco”)">Valor padrão</th><th class="adv" title="Número máximo de caracteres (0 = sem limite)">Máx.</th><th class="adv" title="Valores permitidos, separados por ; (vazio = qualquer)">Lista válida</th><th></th></tr></thead><tbody>${linhas}</tbody></table></div>
    <div class="row"><button class="btn sm" type="button" data-act="mc-add">＋ Coluna</button><span class="hint">“Vai receber” = de onde o app tira o dado. “(em branco)” deixa a coluna vazia, para campos que só o outro sistema tem. Colunas desmarcadas em “Usar” não saem no arquivo.</span></div>`);
}
